    @Test
    void lifecycleAndDocument() throws Exception {
        long id = create(301, "2027-03-10", "2027-03-12", 4, "STANDARD");
        String p = "/reservations/" + id;
        assertError(call("GET", p + "/document", null), 409, "OPERATION_NOT_ALLOWED");
